def get_min_dist(seq, target):
    sums = {0}
    for x in seq:
        new_sums = set()
        for s in sums:
            new_sums.add(s + x)
        sums.update(new_sums)

    min_dist = float('inf')
    for s in sums:
        min_dist = min(min_dist, abs(s - target))
    return min_dist

